import sys, json, random, fractions, bisect, importlib.util
spec=importlib.util.spec_from_file_location('submission','/app/submission/main.py')
sub=importlib.util.module_from_spec(spec); spec.loader.exec_module(sub)

def reference(doc):
    m=doc['model']; cfg=doc['config']; C=m['classes']; W=cfg['window']
    declarations=doc['connections']; byid={x['id']:x for x in declarations}
    slots=[None]*cfg['slots']; generations=[0]*cfg['slots']
    lanes=[0]*cfg['lanes']; jobs=[]; pending=[]
    credit=cfg['initial_tokens']*cfg['rate_den']; last_refill=0
    out_packets=[]
    stats=[{'id':x['id'],'split':x['split'],'label':x['label'],'packets':0,
            'votes':[0]*C,'prediction':None} for x in declarations]
    stats_by_id={x['id']:s for x,s in zip(declarations,stats)}
    def cnn(window):
        x=[m['length_embedding'][a]+m['gap_embedding'][b] for a,b in window]
        pooled=[]
        for f in range(len(m['conv_weights'])):
            vals=[]
            for j in range(W-m['kernel']+1):
                z=m['conv_bias'][f]
                for k in range(m['kernel']):
                    for d in range(2*m['embedding_dim']):
                        z += m['conv_weights'][f][k][d]*x[j+k][d]
                shift=m['conv_shift'][f]
                if shift:
                    sign=-1 if z<0 else 1
                    mag=abs(z); scale=1<<shift
                    z=sign*((2*mag+scale)//(2*scale))
                vals.append(max(0,min(127,z)))
            pooled.append(max(vals))
        logits=[m['dense_bias'][c]+sum(m['dense_weights'][c][f]*pooled[f]
                    for f in range(len(pooled))) for c in range(C)]
        pred=max(range(C),key=lambda c:(logits[c],-c))
        return logits,pred
    def finish(done_jobs):
        nonlocal pending
        for _,jid in done_jobs:
            j=jobs[jid]; o=slots[j['slot']]
            if o is None or o['id']!=j['connection'] or generations[j['slot']]!=j['generation']:
                j['status']='stale'
            elif jid<=o['applied']:
                j['status']='superseded'
            else:
                o['cache']=j['prediction']; o['applied']=jid; j['status']='applied'
        finished={jid for _,jid in done_jobs}
        pending=[item for item in pending if item[1] not in finished]
    for pi,p in enumerate(doc['packets']):
        t=p['time']; due=sorted((item for item in pending if item[0]<=t),key=lambda x:(x[0],x[1]))
        finish(due)
        credit=min(cfg['bucket_capacity']*cfg['rate_den'],credit+(t-last_refill)*cfg['rate_num']); last_refill=t
        decl=byid[p['connection']]; sn=decl['slot']; o=slots[sn]
        if o is None or o['id']!=p['connection'] or t-o['last']>=cfg['idle_timeout']:
            generations[sn]+=1
            o={'id':p['connection'],'last':t,'window':[],'cache':None,'applied':-1,'anchor':t,'backlog':0}
            slots[sn]=o; gap=0
        else: gap=t-o['last']
        o['last']=t
        row=(min(15,p['length']//cfg['len_quantum']),min(15,gap//cfg['gap_quantum']))
        o['window']=(o['window']+[row])[-W:]; o['backlog']+=1
        forward=o['cache'] if o['cache'] is not None else cfg['fallback']
        st=stats_by_id[p['connection']]; st['packets']+=1; st['votes'][forward]+=1
        jid=None
        if len(o['window'])<W: decision='warmup'
        else:
            ti=t-o['anchor']; ci=o['backlog']
            tb=max(i for i,e in enumerate(cfg['time_edges']) if e<=ti)
            cb=max(i for i,e in enumerate(cfg['count_edges']) if e<=ci)
            if p['draw']>=cfg['probability'][tb][cb]: decision='probability'
            elif credit<cfg['rate_den']: decision='tokens'
            elif len(pending)>=cfg['pending_capacity']: decision='queue'
            else:
                decision='sent'; credit-=cfg['rate_den']; jid=len(jobs)
                window=[list(r) for r in o['window']]
                logits,pred=cnn(window)
                lane=min(range(cfg['lanes']),key=lambda l:(lanes[l],l))
                start=max(t,lanes[lane]); done=start+cfg['service'][pred]; lanes[lane]=done
                jobs.append({'id':jid,'packet':pi,'connection':p['connection'],'slot':sn,
                    'generation':generations[sn],'lane':lane,'start':start,'done':done,
                    'window':window,'logits':logits,'prediction':pred,'status':None})
                pending.append((done,jid)); o['anchor']=t; o['backlog']=0
        out_packets.append({'index':pi,'connection':p['connection'],'generation':generations[sn],
            'forward':forward,'decision':decision,'credit':credit,'job':jid})
    finish(sorted(pending,key=lambda x:(x[0],x[1])))
    for st in stats:
        if st['packets']: st['prediction']=max(range(C),key=lambda c:(st['votes'][c],-c))
    reports={}
    for split in ('dev','eval'):
        conf=[[0]*C for _ in range(C)]; observed=0
        for st in stats:
            if st['split']==split and st['packets']:
                observed+=1; conf[st['label']][st['prediction']]+=1
        total=fractions.Fraction(0)
        for c in range(C):
            tp=conf[c][c]; fp=sum(conf[r][c] for r in range(C))-tp
            fn=sum(conf[c])-tp; den=2*tp+fp+fn
            total += fractions.Fraction(2*tp,den) if den else fractions.Fraction(0)
        total/=C
        reports[split]={'connections':observed,'confusion':conf,'macro_f1':[total.numerator,total.denominator]}
    return {'packets':out_packets,'jobs':jobs,'connections':stats,'reports':reports}

def ri(rng,a,b): return rng.randint(a,b)
def make_doc(rng):
    C=ri(rng,2,8); E=ri(rng,1,4); W=ri(rng,1,10); K=ri(rng,1,min(5,W)); F=ri(rng,1,8)
    def i8(): return ri(rng,-128,127)
    def bias():
        return rng.choice([ri(rng,-1000,1000),-2147483648,2147483647,ri(rng,-2**31,2**31-1)])
    m={'classes':C,'embedding_dim':E,
       'length_embedding':[[i8() for _ in range(E)] for _ in range(16)],
       'gap_embedding':[[i8() for _ in range(E)] for _ in range(16)],'kernel':K,
       'conv_weights':[[[i8() for _ in range(2*E)] for _ in range(K)] for _ in range(F)],
       'conv_bias':[bias() for _ in range(F)],'conv_shift':[ri(rng,0,16) for _ in range(F)],
       'dense_weights':[[i8() for _ in range(F)] for _ in range(C)],
       'dense_bias':[bias() for _ in range(C)]}
    nt=ri(rng,1,5); nc=ri(rng,1,5)
    def edges(n,hi):
        vals=[0]
        while len(vals)<n:
            x=ri(rng,0,min(hi,100))
            if x not in vals: vals.append(x)
        return sorted(vals)
    cap=ri(rng,1,10); den=ri(rng,1,20)
    cfg={'slots':ri(rng,1,5),'window':W,'idle_timeout':ri(rng,1,40),
       'len_quantum':ri(rng,1,30),'gap_quantum':ri(rng,1,20),
       'rate_num':ri(rng,1,20),'rate_den':den,'bucket_capacity':cap,'initial_tokens':ri(rng,0,cap),
       'pending_capacity':ri(rng,1,8),'lanes':ri(rng,1,4),
       'service':[ri(rng,1,15) for _ in range(C)],'fallback':ri(rng,0,C-1),
       'time_edges':edges(nt,10**12),'count_edges':edges(nc,20000),
       'probability':[[rng.choice([0,65536,ri(rng,0,65536),1,65535]) for _ in range(nc)] for _ in range(nt)]}
    nconn=ri(rng,0,8); declarations=[]
    for i in range(nconn):
        declarations.append({'id':f'c{i}','slot':ri(rng,0,cfg['slots']-1),'label':ri(rng,0,C-1),
            'split':rng.choice(['dev','eval'])})
    packets=[]; t=0
    if nconn:
        for _ in range(ri(rng,0,160)):
            t += rng.choice([0,0,0,1,1,2,3,5,10,30,100])
            packets.append({'time':t,'connection':rng.choice(declarations)['id'],
                'length':rng.choice([0,65535,ri(rng,0,1000)]),'draw':ri(rng,0,65535)})
    return {'version':1,'config':cfg,'model':m,'connections':declarations,'packets':packets}

def normalized(doc):
    m,c,d,p=sub.validate(doc)
    return sub.replay(m,c,d,p)

def main_test(n=1500,seed=984321):
    rng=random.Random(seed)
    for i in range(n):
        doc=make_doc(rng)
        a=normalized(doc); b=reference(doc)
        if a!=b:
            json.dump(doc,open('/app/tmp/failure.json','w'))
            # locate first difference
            for key in a:
                if a[key]!=b[key]: print('mismatch case',i,'section',key)
            raise SystemExit(1)
        if i%250==0: print('passed',i)
    print('all randomized differential cases passed:',n)
if __name__=='__main__': main_test()
